Synopsis: Remove a callback that was registered using vhpi_register_cb()
Syntax: vhpi_remove_cb(cbHdl)
Arguments: vhpiHandleT cbHdl A callback handle of kind vhpiCallbackK
Related functions: Use vhpi_register_cb() to register a callback
The vhpi_remove_cb() function removes a callback that was registered using
vhpi_register_cb(). The argument to this function is a handle to the callback. The
function returns 0 on success and a 1 on failure. After the callback is removed, the
callback handle becomes invalid (the interface implicitly frees up any internal storage that
was allocated for the callback including the callback handle).
int find_cbk(vhpiHandleT objHdl)
{
vhpiHandleT cbHdl, cbItr;
vhpiCbDataT cbdata;
int found = 0;
/* find a specific callback on value change
that was registered for object and remove it */
cbItr = vhpi_iterator(vhpiCallbacks, objHdl);
if (!cbItr) return;
while (cbHdl = vhpi_scan(cbItr))
{
vhpi_get_cb_info(cbHdl, &cbdata);
if ((int)(cbdata.user_data) == 2)
{
vhpi_remove_cb(cbHdl);
found = 1;
break;
}
}
vhpi_release_handle(cbItr); /* free the iterator */
return(found);
}

