vlogan -sverilog -ntb_opts uvm +define+UMV_MSG_ALIGN top.sv

uvm_report_object log;
string process_name = "top.sysc.uvmconn1.driver";
// call task with package-XMR
log =
tli_uvm_msg_align_pkg::tli_util_uvm_sysc_get_log_by_instName(process_nam
e);
if (log)
// switch off warnings
