SystemC Module Using Byte Packing
The SystemC module, which is instantiated, requires two byte pack including
tli_packunpack.h and tli_packunpack_MemAccess.h.
The following is the BusModel.h header file:
#ifndef BUS_MODEL_H
#define BUS_MODEL_H

#include <tli_packunpack.h>
#include "tli_packunpack_MemAccess.h"

SC_MODULE(BusModel)
{
sc_in<bool> clock;
SC_CTOR(BusModel)
: clock("clock")
{
m_mem = new unsigned char[m_size];
for (int n=0; n<m_size; n++)
m_mem[n] = n % 100;

SC_THREAD(do_transactions);
sensitive_pos << clock;
}

void do_transactions();

private:
static const int m_size;
unsigned char* m_mem;

};

The BusModel method do_transaction calls for byte packing the
tli_conv2_pack_MemAccess(pba, trans) function and for unpacking

tli_conv2_unpack_MemAccess(pba, trans), where pba is a tli_pack_data object
configured for OVM and trans is a MemAccess instantiation. With the tli_pack_data
upload and download functions, the byte buffer is loaded or sent from or to SV.
The following is the BusModel.cpp file:
#include <BusModel.h>

extern "C" void io_printf(const char *format, );
void print_MemAccess(const MemAccess& T)
{

io_printf("MemAccess object:\n");
io_printf("adr=%0d RW=%0d len=%0d\n",
T.adr, T.RW, T.len);
for (n=0; n<T.len; n=n+1)
io_printf("data[%0d]=%0d\n", n, T.data[n]);
io_printf("end object\n");
}

void BusModel::do_transactions()
{
tli_pack_data pba(TLI_OVM_PACK);
MemAccess trans;

while(1) {
// get next transaction
wait();
wait(5,SC_NS);
io_printf("--- now download and unpack on C++ side\n");
//load the byte buffer from SV
pba.download(0);
tli_conv2_unpack_MemAccess( pba, trans );
io_printf("===PACK_UNPACK_BEGIN output sv2sc\n");
print_MemAccess( trans );
io_printf("===PACK_UNPACK_END output sv2sc\n");

io_printf("---\n");
io_printf("--- Test direction C++ --> SV\n");
io_printf("---\n");
io_printf("--- Modify transaction to fully test reverse direction\n");
io_printf("--- Pack and upload on C++ side\n");
trans.adr++;
trans.len--;

// execute transaction
for (int n=0; (n<trans.len) && ((trans.adr+n)<m_size); n++) {
if (trans.RW) {
trans.data[n] = m_mem[trans.adr + n];
} else {
m_mem[trans.adr + n] = trans.data[n];

}
}

wait(10,SC_NS);
io_printf("===PACK_UNPACK_BEGIN input sc2sv\n");
print_MemAccess( trans );
io_printf("===PACK_UNPACK_END input sc2sv\n");
// Reset the byte buffer (prepare for upload)
pba.reset();
tli_conv2_pack_MemAccess( pba, trans );
// Send the byte buffer to SV by pba.upload(0);
pba.upload(0);

return; // do just one transfer SV->C++ and back
}
}

