parameter PERIOD = 20;
reg clock;
reg [`W:0] value1;
reg [`W:0] value2;
wire [`W:0] add_wire;

integer counter;
integer direction;

integer cycle;

// SystemC model
adder add1(value1, value2, add_wire);

value1 = 32'b010; // starts at 2
value2 = 32'b000; // starts at 0
counter = 0;
direction = 1;
cycle = 0;
end

// clock generator
always begin
clock = 1'b0;
#PERIOD
forever begin
#(PERIOD/2) clock = 1'b1;
#(PERIOD/2) clock = 1'b0;
end
end

// stimulus generator
always @(posedge clock) begin
value1 <= counter+2;
value2 <= 32'b010; // stays at 2 after here.

if (direction == 1) // incrementing
if (counter == 9) begin
counter = counter - 1;
direction = 0;
end
else
counter = counter + 1;
else // decrementing
if (counter == 0) begin
counter = counter + 1;
direction = 1;
end
else
counter = counter - 1;
end

)}
where,
myfunc - name of the function
reg_r1 - Verilog signal in which to store the return value. This signal must be declared in
the Verilog code.
a, b - Function inputs.

Example for Calling SystemVerilog Class Methods
Consider the following example testcase call.sv:
program P1;
