`include "vllogic.v"
module vltop;
reg a,b,c;
wire d,e;
vhent vh1(.a(a), .b(b), .c(c), .d(d), .e(e));
$monitor("a=%b b = %b c=%b d=%b e=%b", a,b,c,d,e,$time);
#2 a = 'b1; b = 'b1; c= 'b0;
#2 a = 'b0; b = 'b1; c= 'b1;
#2 a = 'b1; b = 'b0; c= 'b0;
end

